const raw = $input.first().json;
const body = raw.body || raw;
const preview = !!body.preview_only;
const approved = !!body.approved;

if (approved) {
  return [{ json: { mode: 'send', to: body.to, subject: body.subject, body: body.body, contact_id: body.contact_id } }];
}

if (preview) {
  const firma = body.firma || 'Ihr Betrieb';
  const kontakt = body.kontakt || '';
  const einwand = (body.einwand || body.notiz || '').trim();
  const anlass = body.anlass || 'sonstiges';
  const nachname = kontakt && kontakt !== 'NA' ? kontakt.split(' ').slice(-1)[0] : null;
  const anrede = nachname ? 'Sehr geehrter Herr ' + nachname : 'Sehr geehrte Damen und Herren';

  let subject = 'Kurze Rückmeldung zu ' + firma;
  let bezug = einwand ? 'Bezugnehmend auf unser Gespräch (' + einwand + ')' : 'Bezugnehmend auf unser Gespräch';

  if (anlass.indexOf('einwand') === 0) {
    subject = 'Zu Ihrem Punkt — ' + firma;
    bezug = einwand ? 'Sie hatten angemerkt: „' + einwand + '“.' : 'Zu Ihrem Einwand möchte ich kurz Stellung nehmen.';
  } else if (anlass === 'demo_nachbereitung') {
    subject = 'Zusammenfassung unserer Demo — ' + firma;
    bezug = 'Vielen Dank für die Zeit in unserer Demo.';
  } else if (anlass === 'nach_call') {
    subject = 'Wie besprochen — ' + firma;
    bezug = 'Wie in unserem Telefonat besprochen, sende ich Ihnen die angekündigten Informationen.';
  }

  const mailBody = anrede + ',\n\n' + bezug + '\n\n' +
    '[Hier 2–3 Sätze Nutzen / konkreter Vorschlag einfügen]\n\n' +
    'Gerne kläre ich offene Fragen in einem kurzen Termin.\n\n' +
    'Mit freundlichen Grüßen\nKevin Ritz\nkevin@ritz-ai.solutions';

  return [{ json: { mode: 'preview', subject: subject, body: mailBody, contact_id: body.contact_id } }];
}

return [{ json: { mode: 'error', message: 'preview_only oder approved erforderlich' } }];
